using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
/* every opening of a CHB wall gets its lintel from the lintel schedule as soon as it is placed (owner, 21 November 2026); the lintels
   are Miscellaneous Structures / Lintel Beam quantities (concrete, forms, rebar) and are listed in their own tab */
partial class ProgramOfWorksForm {
 CheckBox autoLintels;DataGridView lintelGrid;Label lintelNote,lintelSummary,chbLintelSummary;static readonly int[] LintelDias={10,12,16,20,25};
 static readonly string[] LintelHeaders={"Lintel","Opening","Wall","CHB","Clear opening m","Units","b x h mm","Bottom","Top","Mid","Ties 10 mm","Bearing each end mm","Length m","Jamb bars each side","Lateral brace","Concrete m3","Formworks m2","RSB 10 mm kg","RSB 12 mm kg","RSB 16 mm kg","RSB 20 mm kg","RSB 25 mm kg","RSB total kg","Status"};
 /* the automatic lintels are shown at the top of the Lintel Beam sheet (owner, 21 November 2026: "automatic na dapat yung quantities
    for lintel kung ano input sa masonry"); the grid under them is for other lintels entered by hand */
 void AddOpeningLintelsTab(){TabPage misc;if(sheetPages==null||!sheetPages.TryGetValue("Miscellaneous Structures",out misc))return;var host=AllControls(misc).OfType<TabControl>().FirstOrDefault();if(host==null)return;
  var page=host.TabPages.Cast<TabPage>().FirstOrDefault(t=>t.Text=="Lintel Beam");if(page==null)return;
  var panel=new Panel{Dock=DockStyle.Top,Height=330,Padding=new Padding(0,0,0,8)};var top=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=true,Padding=new Padding(0,0,0,4)};
  top.Controls.Add(new Label{Text="LINTELS OVER OPENINGS - automatic from the masonry walls and their openings",AutoSize=true,Font=ModernUi.Strong,ForeColor=PowTheme.Ink,Margin=new Padding(3,11,16,3)});
  autoLintels=new CheckBox{Text="Add automatically",Checked=true,AutoSize=true,Margin=new Padding(3,9,12,3)};autoLintels.CheckedChanged+=(s,e)=>{if(extraReady&&!filling)Recalculate();};top.Controls.Add(autoLintels);
  var edit=new Button{Text="Edit lintel reinforcement schedule",AutoSize=true,Height=34};edit.Click+=(s,e)=>{if(EditLintelSchedule())Recalculate();};top.Controls.Add(edit);
  lintelNote=new Label{Dock=DockStyle.Top,AutoSize=false,Height=40,ForeColor=PowTheme.Muted,Padding=new Padding(2,2,2,2),Text="Mark from the CHB thickness and the clear opening (between two ranges the larger mark), per the lintel reinforcement schedule (the Lintel Beam Design Calculation Report unless edited). Gravity load with at most 2.5 m of CHB wall above. Separate Bill of Quantities item: Lintel Beam over Openings. Enter only other lintels in the grid below."};
  lintelSummary=new Label{Dock=DockStyle.Top,AutoSize=false,Height=28,Font=ModernUi.Strong,ForeColor=PowTheme.Teal,TextAlign=ContentAlignment.MiddleLeft};
  lintelGrid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};foreach(var h in LintelHeaders)lintelGrid.Columns.Add(h,h);foreach(DataGridViewColumn c in lintelGrid.Columns)c.SortMode=DataGridViewColumnSortMode.NotSortable;
  var manual=new Label{Dock=DockStyle.Bottom,Height=26,Text="OTHER LINTELS (entered by hand)",Font=ModernUi.Strong,ForeColor=PowTheme.Ink,TextAlign=ContentAlignment.BottomLeft};
  panel.Controls.Add(lintelGrid);panel.Controls.Add(lintelSummary);panel.Controls.Add(lintelNote);panel.Controls.Add(top);panel.Controls.Add(manual);
  page.Controls.Add(panel);page.Controls.SetChildIndex(panel,page.Controls.Count-1);
  /* the automatic lintels and the lintels entered by hand share the sheet equally (owner, 23 November 2026: "equal space ng dalawang
     input ng lintel beams") */
  EventHandler half=(s,e)=>{int h=page.ClientSize.Height/2;if(h>=260&&panel.Height!=h)panel.Height=h;};page.Resize+=half;page.VisibleChanged+=half;half(null,EventArgs.Empty);
  TabPage chb;if(sheetPages.TryGetValue("CHB Estimate",out chb)){chbLintelSummary=new Label{Dock=DockStyle.Top,AutoSize=false,Height=30,Font=ModernUi.Strong,ForeColor=PowTheme.Teal,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(6,0,0,0)};chb.Controls.Add(chbLintelSummary);chb.Controls.SetChildIndex(chbLintelSummary,chb.Controls.Count-1);}}
 /* the reinforcement schedule editor: one row per mark, checked before it is used; Reset gives the report's schedule back */
 bool EditLintelSchedule(){string[] heads={"Mark","CHB (4 / 6)","Largest clear opening m","b mm","h mm","Bottom bars","Top bars","Mid bars","Ties (single / closed)","Tie spacing mm","Bearing each end mm","Lateral brace"};
  using(var form=new Form{Text="Lintel reinforcement schedule",Width=1180,Height=520,StartPosition=FormStartPosition.CenterParent,Font=Font,MinimizeBox=false}){AppBrand.Apply(form);
   var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=true,AllowUserToDeleteRows=true,RowHeadersVisible=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White};foreach(var h in heads)grid.Columns.Add(h,h);
   Action<IEnumerable<LintelMark>> fill=marks=>{grid.Rows.Clear();foreach(var m in marks)grid.Rows.Add(LintelSchedule.Text(m).Split('|').Select(x=>(object)(x==""?"-":x)).ToArray());};fill(LintelSchedule.Current);
   var note=new Label{Dock=DockStyle.Top,Height=44,Padding=new Padding(8,6,8,0),ForeColor=PowTheme.Muted,Text="Bars as count-diameter (2-16; 0-10 or - for none). A mark is used for openings up to its largest clear opening; the next larger mark of the same CHB takes the rest. Saved with the project. Reset gives the Lintel Beam Design Calculation Report schedule back."};
   var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=52,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(8)};var ok=new Button{Text="Use this schedule",AutoSize=true,Height=34};var cancel=new Button{Text="Cancel",AutoSize=true,Height=34,DialogResult=DialogResult.Cancel};var reset=new Button{Text="Reset to the report",AutoSize=true,Height=34};
   bar.Controls.Add(ok);bar.Controls.Add(cancel);bar.Controls.Add(reset);form.Controls.Add(grid);form.Controls.Add(note);form.Controls.Add(bar);form.CancelButton=cancel;reset.Click+=(s,e)=>fill(LintelSchedule.Defaults);
   List<LintelMark> result=null;ok.Click+=(s,e)=>{grid.EndEdit();try{var list=new List<LintelMark>();foreach(DataGridViewRow r in grid.Rows){if(r.IsNewRow)continue;Func<int,string> v=k=>Convert.ToString(r.Cells[k].Value);if(Enumerable.Range(0,heads.Length).All(k=>v(k).Trim()==""))continue;list.Add(LintelSchedule.Parse(v(0),v(1),v(2),v(3),v(4),v(5),v(6),v(7),v(8),v(9),v(10),v(11)));}
     if(!list.Any(m=>m.Chb==4)||!list.Any(m=>m.Chb==6))throw new Exception("Keep at least one 4\" and one 6\" mark.");if(list.GroupBy(m=>m.Mark,StringComparer.OrdinalIgnoreCase).Any(g=>g.Count()>1))throw new Exception("Each mark once.");result=list;form.DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(form,ex.Message,"Lintel reinforcement schedule");}};
   if(form.ShowDialog(this)!=DialogResult.OK||result==null)return false;LintelSchedule.Current=result;return true;}}
 static IEnumerable<Control> AllControls(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in AllControls(c))yield return d;}}
 void RecalculateOpeningLintels(){lintelResults.Clear();if(lintelGrid!=null)lintelGrid.Rows.Clear();if(autoLintels!=null&&!autoLintels.Checked){ShowLintelTotals();return;}LengthConfiguration cfg;try{cfg=ExtraConfiguration("Lintel Beam");}catch(Exception){ShowLintelTotals();return;}
  var walls=wallItems.Where(w=>w.Material=="CHB").ToDictionary(w=>w.Id.Trim(),StringComparer.OrdinalIgnoreCase);
  foreach(var o in wallOpenings){WallItem wall;if(o==null||o.Wall==null||!walls.TryGetValue(o.Wall.Trim(),out wall))continue;
   try{LintelMark mark;var q=LintelSchedule.Takeoff(o,wall,cfg,out mark);miscQuantities.Add(q);miscPlan.AddRange(CommercialBars.Allocate(new[]{q.Steel},cfg,miscStock));
    lintelResults.Add(q);if(lintelGrid!=null){var cells=new System.Collections.Generic.List<object>{mark.Mark,o.Id,wall.Id,mark.Chb+"\"",o.Width.ToString("0.00",CultureInfo.InvariantCulture),q.Quantity,mark.Width+" x "+mark.Depth,mark.Bottom,mark.Top,mark.Mid,mark.Ties,mark.Bearing,(o.Width+2*mark.Bearing/1000.0).ToString("0.00",CultureInfo.InvariantCulture),mark.JambBarsPerSide+"-12",mark.Brace==""?"-":"Wall bars 10 mm @ 800 (not included)",q.Concrete.ToString("0.000",CultureInfo.InvariantCulture),q.Forms.ToString("0.00",CultureInfo.InvariantCulture)};
     foreach(int d in LintelDias)cells.Add(Kg(q,d)>0?Kg(q,d).ToString("0.00",CultureInfo.InvariantCulture):"");cells.Add(q.Steel.Result.Total.ToString("0.00",CultureInfo.InvariantCulture));cells.Add(wall.ThicknessMm>150?"6\" marks used for a "+wall.ThicknessMm.ToString("0",CultureInfo.InvariantCulture)+" mm wall - check":"Estimated");lintelGrid.Rows.Add(cells.ToArray());}}
   catch(Exception ex){errors.Add("Lintel over "+o.Id+" in wall "+wall.Id+": "+ex.Message);if(lintelGrid!=null){var cells=new object[lintelGrid.Columns.Count];cells[0]="-";cells[1]=o.Id;cells[2]=wall.Id;cells[cells.Length-1]=ex.Message;lintelGrid.Rows.Add(cells);}}}
  ShowLintelTotals();}
 readonly System.Collections.Generic.List<MiscStructureQuantity> lintelResults=new System.Collections.Generic.List<MiscStructureQuantity>();
 static double Kg(MiscStructureQuantity q,int dia){return q.Steel.Result.Lines.Where(l=>l.Diameter==dia).Sum(l=>l.Kg);}
 /* totals at once (owner, 21 November 2026: "compute mo na agad yung concrete, RSB, formworks"): the 12 mm jamb bars are included,
    the lateral brace is the wall's own vertical reinforcement and is not added here */
 void ShowLintelTotals(){int n=lintelResults.Sum(q=>q.Quantity);double c=lintelResults.Sum(q=>q.Concrete),f=lintelResults.Sum(q=>q.Forms),kg=lintelResults.Sum(q=>q.Steel.Result.Total);
  string dias=string.Join(", ",LintelDias.Where(d=>lintelResults.Sum(q=>Kg(q,d))>0).Select(d=>d+" mm "+lintelResults.Sum(q=>Kg(q,d)).ToString("0.00",CultureInfo.InvariantCulture)+" kg"));
  string text=n==0?"No lintels: assign openings to CHB walls (Door & Window Schedule or the wall's openings).":"LINTELS OVER OPENINGS: "+n+" lintel"+(n==1?"":"s")+"  |  Concrete "+c.ToString("0.000",CultureInfo.InvariantCulture)+" m3  |  Formworks "+f.ToString("0.00",CultureInfo.InvariantCulture)+" m2  |  RSB "+kg.ToString("0.00",CultureInfo.InvariantCulture)+" kg ("+dias+"), 12 mm jamb bars included, lateral brace not included";
  if(lintelSummary!=null)lintelSummary.Text=text;if(chbLintelSummary!=null)chbLintelSummary.Text=autoLintels!=null&&!autoLintels.Checked?"Automatic lintels are off (Miscellaneous Structures > Lintels over Openings).":text;
  if(lintelGrid!=null&&n>0){var cells=new object[lintelGrid.Columns.Count];cells[0]="TOTAL";cells[5]=n;cells[15]=c.ToString("0.000",CultureInfo.InvariantCulture);cells[16]=f.ToString("0.00",CultureInfo.InvariantCulture);for(int k=0;k<LintelDias.Length;k++){double v=lintelResults.Sum(q=>Kg(q,LintelDias[k]));cells[17+k]=v>0?v.ToString("0.00",CultureInfo.InvariantCulture):"";}cells[22]=kg.ToString("0.00",CultureInfo.InvariantCulture);int r=lintelGrid.Rows.Add(cells);lintelGrid.Rows[r].DefaultCellStyle.Font=new Font(lintelGrid.Font,FontStyle.Bold);lintelGrid.Rows[r].DefaultCellStyle.BackColor=Color.FromArgb(236,243,239);}}
}
}
